/**
 * 维护窗口类型：初始登记（REGISTER）或对已封存窗口的事后更正（CORRECTION）。
 */
public enum WindowType {
    /**
     * 站点维护窗口的初始登记。
     */
    REGISTER,
    /**
     * 对已被合并快照封存、不可修改的历史窗口追加的更正窗口。
     */
    CORRECTION
}

package com.example.starter.maintenance;

/**
 * 维护窗口状态：ACTIVE 表示生效中（观测提交按其匹配），DELETED 表示已删除；
 * 已被合并快照封存的窗口不允许删除，只能追加更正窗口。
 */
public enum WindowStatus {
    /**
     * 生效中：参与观测提交的维护命中匹配。
     */
    ACTIVE,
    /**
     * 已删除：不再参与匹配；历史快照中固化的引用不受影响。
     */
    DELETED
}

package com.example.starter.maintenance;

/**
 * 冲突簇合并快照状态：MERGED 表示自动合并选出胜出版本，
 * PENDING_MANUAL 表示簇内观测全部受维护影响，不自动选胜出，等待人工裁决。
 */
public enum SnapshotStatus {
    /**
     * 自动合并完成：已从未受维护影响的观测中选出胜出版本。
     */
    MERGED,
    /**
     * 待人工裁决：冲突簇只含 MAINTENANCE_AFFECTED 观测，不自动选胜出。
     */
    PENDING_MANUAL
}

