                    }
                },
                () -> {
                    try {
                        maintenanceService.adjudicateCluster("cl-2", new AdjudicateClusterRequest(
                                "req-ca-2", "adj-2", "obs-b", "选择B", "op-2"));
                        return "ok-b";
                    } catch (MaintenanceApiException e) {
